require_once __DIR__.'/../../app/helpers.php';require_role('candidate');if($_SERVER['REQUEST_METHOD']!=='POST')redirect('jobs.php');verify_csrf();$jid=(int)($_POST['job_id']??0);$st=db()->prepare("SELECT id FROM jobs WHERE id=? AND status='Aktif' AND (deadline IS NULL OR deadline>=CURDATE())");$st->execute([$jid]);if(!$st->fetchColumn()){flash('error','Lowongan tidak tersedia atau sudah melewati batas lamaran.');redirect('jobs.php');}try{$st=db()->prepare("INSERT INTO applications(job_id,candidate_id,cover_letter,status) VALUES(?,?,?,'Menunggu')");$st->execute([$jid,current_user()['id'],trim($_POST['cover_letter']??'')]);flash('success','Lamaran berhasil dikirim.');}catch(PDOException $e){flash('error','Kamu sudah pernah melamar lowongan ini.');}redirect('candidate/applications.php');
